package me.avinas.tempo.data.local

import com.squareup.moshi.Moshi
import java.io.File
import java.sql.Connection
import java.util.Locale

/**
 * The database schemas Room actually exported at build time, read back from `app/schemas`.
 *
 * A migration test that hand-writes the "before" schema is only ever as truthful as whoever
 * typed it: it drifts the moment a release changes a column, and it never notices, because the
 * fixture is not generated by anything. These are the files the Room compiler wrote for each
 * shipped version, so a database built from one is the database a real install of that version
 * carries -- DDL, indices and identity hash included.
 *
 * The schema JSON is also the authority Room itself validates against at open time, which is
 * what makes it the right yardstick for the upgrade: if the migrated database matches
 * `58.json`, Room's `onValidateSchema` has nothing to complain about, and the app opens.
 */

/** A column as exported: name, declared affinity, nullability and (if any) declared default. */
data class ExportedColumn(
    val name: String,
    val affinity: String,
    val notNull: Boolean,
    val defaultValue: String?,
)

data class ExportedIndex(
    val name: String,
    val unique: Boolean,
    val columns: List<String>,
    val createSql: String,
)

data class ExportedForeignKey(
    val table: String,
    val onDelete: String,
    val onUpdate: String,
    val columns: List<String>,
    val referencedColumns: List<String>,
)

data class ExportedTable(
    val name: String,
    val createSql: String,
    val columns: List<ExportedColumn>,
    val primaryKey: List<String>,
    val indices: List<ExportedIndex>,
    val foreignKeys: List<ExportedForeignKey>,
) {
    fun column(name: String): ExportedColumn = columns.first { it.name == name }

    fun hasColumn(name: String): Boolean = columns.any { it.name == name }
}

/**
 * One version's exported schema. `setupQueries` carries the `room_master_table` DDL and the
 * identity-hash insert Room runs after `createAllTables`, so applying them puts the database in
 * exactly the state a freshly created install of that version is in.
 */
data class ShippedSchema(
    val version: Int,
    val identityHash: String,
    val tables: List<ExportedTable>,
    val setupQueries: List<String>,
) {
    val tableNames: Set<String> = tables.map { it.name }.toSet()

    fun table(name: String): ExportedTable = tables.first { it.name == name }

    /**
     * Builds this schema in [connection] the way Room builds it: every entity's `createSql`,
     * every index, then the setup queries, then the version stamp SQLite keeps.
     */
    fun createIn(connection: Connection) {
        connection.createStatement().use { statement ->
            statement.execute("PRAGMA foreign_keys = OFF")
            tables.forEach { table ->
                statement.execute(table.createSql.replace("\${TABLE_NAME}", table.name))
                table.indices.forEach { index ->
                    statement.execute(index.createSql.replace("\${TABLE_NAME}", table.name))
                }
            }
            setupQueries.forEach { statement.execute(it) }
            statement.execute("PRAGMA user_version = $version")
        }
    }
}

object ShippedSchemas {

    private const val SCHEMA_DIR = "schemas/me.avinas.tempo.data.local.AppDatabase"

    private val moshi = Moshi.Builder().build()

    /**
     * AGP runs unit tests with the module directory as the working directory, but which directory
     * that is has moved between AGP majors, so all the plausible roots are tried before giving up.
     * Failing loudly beats silently testing nothing.
     */
    val directory: File by lazy {
        val candidates =
            listOf(
                File(SCHEMA_DIR),
                File("app/$SCHEMA_DIR"),
                File("../$SCHEMA_DIR"),
                File(System.getProperty("user.dir"), SCHEMA_DIR),
                File(System.getProperty("user.dir"), "app/$SCHEMA_DIR"),
            )
        candidates.firstOrNull { it.isDirectory }
            ?: throw IllegalStateException(
                "Room's exported schemas were not found. Looked in: " +
                    candidates.joinToString { it.absolutePath } +
                    ". Run the tests through Gradle from the repository root -- the exported " +
                    "JSON under app/schemas is the fixture every upgrade test here is built from.",
            )
    }

    /**
     * Every schema that was inside a release users actually run: 43 through 55. Schemas 56 and 57
     * were built locally only and never shipped, which is why no database in the wild is on them,
     * and why `MIGRATION_55_58` exists as one step rather than three.
     */
    val shippedVersions: List<Int> by lazy {
        directory.listFiles { file -> file.extension == "json" }
            .orEmpty()
            .map { it.nameWithoutExtension.toInt() }
            .filter { it < AppDatabase.VERSION }
            .sorted()
    }

    fun load(version: Int): ShippedSchema {
        val file = File(directory, "$version.json")
        require(file.isFile) { "no exported schema for version $version at ${file.absolutePath}" }

        @Suppress("UNCHECKED_CAST")
        val root = moshi.adapter(Any::class.java).fromJson(file.readText()) as Map<String, Any?>
        @Suppress("UNCHECKED_CAST")
        val database = root["database"] as Map<String, Any?>

        @Suppress("UNCHECKED_CAST")
        val entities = database["entities"] as List<Map<String, Any?>>

        return ShippedSchema(
            version = (database["version"] as Double).toInt(),
            identityHash = database["identityHash"] as String,
            setupQueries = strings(database["setupQueries"]),
            tables = entities.map { entity -> entity.toExportedTable() },
        )
    }

    @Suppress("UNCHECKED_CAST")
    private fun Map<String, Any?>.toExportedTable(): ExportedTable {
        val name = this["tableName"] as String
        return ExportedTable(
            name = name,
            createSql = this["createSql"] as String,
            columns =
                (this["fields"] as List<Map<String, Any?>>).map { field ->
                    ExportedColumn(
                        name = field["columnName"] as String,
                        affinity = field["affinity"] as String,
                        notNull = field["notNull"] as Boolean? ?: false,
                        defaultValue = field["defaultValue"] as String?,
                    )
                },
            primaryKey = strings((this["primaryKey"] as Map<String, Any?>)["columnNames"]),
            indices =
                (this["indices"] as List<Map<String, Any?>>? ?: emptyList()).map { index ->
                    ExportedIndex(
                        name = index["name"] as String,
                        unique = index["unique"] as Boolean? ?: false,
                        columns = strings(index["columnNames"]),
                        createSql = index["createSql"] as String,
                    )
                },
            foreignKeys =
                (this["foreignKeys"] as List<Map<String, Any?>>? ?: emptyList()).map { key ->
                    ExportedForeignKey(
                        table = key["table"] as String,
                        onDelete = key["onDelete"] as String,
                        onUpdate = key["onUpdate"] as String,
                        columns = strings(key["columns"]),
                        referencedColumns = strings(key["referencedColumns"]),
                    )
                },
        )
    }

    @Suppress("UNCHECKED_CAST")
    private fun strings(value: Any?): List<String> = (value as List<Any?>? ?: emptyList()).map { it as String }
}

// ---- Reading a live database back the way Room reads it ---------------------

/**
 * What Room's `TableInfo.read` sees in a live database, built from the same PRAGMAs:
 * `table_info`, `index_list`/`index_info` and `foreign_key_list`.
 *
 * [diffAgainst] answers the only question that matters before shipping an upgrade -- "would
 * Room's `onValidateSchema` accept this database for the schema this build compiles?" -- and
 * answers it as a list of human-readable mismatches rather than a stack trace, so a failure says
 * which column drifted instead of that something did.
 */
class LiveDatabase(private val connection: Connection) {

    data class Column(
        val name: String,
        val affinity: String,
        val notNull: Boolean,
        val primaryKeyPosition: Int,
        val defaultValue: String?,
    )

    data class Index(val name: String, val unique: Boolean, val columns: List<String>)

    data class ForeignKey(
        val table: String,
        val onDelete: String,
        val onUpdate: String,
        val columns: List<String>,
        val referencedColumns: List<String>,
    )

    data class Table(
        val name: String,
        val columns: Map<String, Column>,
        val indices: Set<Index>,
        val foreignKeys: Set<ForeignKey>,
    )

    /** Tables Room does not model but the platform or Room itself creates. */
    private val infrastructureTables = setOf("room_master_table", "android_metadata")

    val tables: Map<String, Table> by lazy { readTables() }

    fun identityHash(): String? =
        connection.createStatement().use { statement ->
            statement.executeQuery("SELECT identity_hash FROM room_master_table WHERE id = 42").use { rs ->
                if (rs.next()) rs.getString(1) else null
            }
        }

    fun userVersion(): Int =
        connection.createStatement().use { statement ->
            statement.executeQuery("PRAGMA user_version").use { rs ->
                rs.next()
                rs.getInt(1)
            }
        }

    private fun readTables(): Map<String, Table> {
        val names = mutableListOf<String>()
        connection.createStatement().use { statement ->
            statement
                .executeQuery("SELECT name FROM sqlite_master WHERE type = 'table' AND name NOT LIKE 'sqlite_%'")
                .use { rs ->
                    while (rs.next()) names.add(rs.getString(1))
                }
        }
        return names.associateWith { readTable(it) }
    }

    private fun readTable(name: String): Table {
        val columns = linkedMapOf<String, Column>()
        connection.createStatement().use { statement ->
            statement.executeQuery("PRAGMA table_info(`$name`)").use { rs ->
                while (rs.next()) {
                    val declaredType = rs.getString("type") ?: ""
                    val column =
                        Column(
                            name = rs.getString("name"),
                            affinity = affinityOf(declaredType),
                            notNull = rs.getInt("notnull") != 0,
                            primaryKeyPosition = rs.getInt("pk"),
                            defaultValue = rs.getString("dflt_value"),
                        )
                    columns[column.name] = column
                }
            }
        }

        val indices = linkedSetOf<Index>()
        val indexNames = mutableListOf<String>()
        connection.createStatement().use { statement ->
            statement.executeQuery("PRAGMA index_list(`$name`)").use { rs ->
                while (rs.next()) {
                    val origin = rs.getString("origin")
                    // `pk` indices are the rowid/PK ones SQLite creates for itself; Room skips them.
                    if (origin != "pk") indexNames.add(rs.getString("name"))
                }
            }
        }
        indexNames.forEach { indexName ->
            val indexColumns = mutableListOf<String>()
            connection.createStatement().use { statement ->
                statement.executeQuery("PRAGMA index_info(`$indexName`)").use { rs ->
                    while (rs.next()) indexColumns.add(rs.getString("name") ?: "")
                }
            }
            val unique =
                connection.createStatement().use { statement ->
                    statement.executeQuery("PRAGMA index_list(`$name`)").use { rs ->
                        var isUnique = false
                        while (rs.next()) {
                            if (rs.getString("name") == indexName) isUnique = rs.getInt("unique") != 0
                        }
                        isUnique
                    }
                }
            indices.add(Index(indexName, unique, indexColumns))
        }

        // Foreign keys: PRAGMA returns one row per column, grouped by `id` and ordered by `seq`.
        val byId = linkedMapOf<Int, MutableList<Array<String>>>()
        val onDeleteById = mutableMapOf<Int, String>()
        val onUpdateById = mutableMapOf<Int, String>()
        val tableById = mutableMapOf<Int, String>()
        connection.createStatement().use { statement ->
            statement.executeQuery("PRAGMA foreign_key_list(`$name`)").use { rs ->
                while (rs.next()) {
                    val id = rs.getInt("id")
                    tableById[id] = rs.getString("table")
                    onDeleteById[id] = rs.getString("on_delete")
                    onUpdateById[id] = rs.getString("on_update")
                    byId.getOrPut(id) { mutableListOf() }
                        .add(arrayOf(rs.getString("from") ?: "", rs.getString("to") ?: ""))
                }
            }
        }
        val foreignKeys =
            byId.map { (id, pairs) ->
                ForeignKey(
                    table = tableById.getValue(id),
                    onDelete = onDeleteById.getValue(id),
                    onUpdate = onUpdateById.getValue(id),
                    columns = pairs.map { it[0] },
                    referencedColumns = pairs.map { it[1] },
                )
            }.toSet()

        return Table(name, columns, indices, foreignKeys)
    }

    /**
     * Every way the live database differs from [expected], phrased so a failure reads as the
     * defect rather than as a mismatched string. An empty list means Room's validation passes.
     */
    fun diffAgainst(expected: ShippedSchema): List<String> {
        val problems = mutableListOf<String>()

        if (userVersion() != expected.version) {
            problems += "user_version is ${userVersion()}, expected ${expected.version}"
        }

        expected.tableNames.filterNot { it in tables }.forEach { problems += "table '$it' is missing" }
        tables.keys
            .filterNot { it in expected.tableNames || it in infrastructureTables }
            .forEach { problems += "table '$it' was left behind by the migration" }

        expected.tables.forEach { expectedTable ->
            val live = tables[expectedTable.name] ?: return@forEach
            problems += diffColumns(expectedTable, live)
            problems += diffIndices(expectedTable, live)
            problems += diffForeignKeys(expectedTable, live)
        }

        return problems
    }

    private fun diffColumns(expected: ExportedTable, live: Table): List<String> {
        val problems = mutableListOf<String>()
        val expectedNames = expected.columns.map { it.name }.toSet()

        expected.columns.forEach { column ->
            val actual = live.columns[column.name]
            if (actual == null) {
                problems += "${expected.name}.${column.name} is missing"
                return@forEach
            }
            if (actual.affinity != column.affinity) {
                problems +=
                    "${expected.name}.${column.name} has affinity ${actual.affinity}, expected ${column.affinity}"
            }
            if (actual.notNull != column.notNull) {
                problems +=
                    "${expected.name}.${column.name} notNull=${actual.notNull}, expected ${column.notNull}"
            }
            val expectedPkPosition = expected.primaryKey.indexOf(column.name) + 1
            if (actual.primaryKeyPosition != expectedPkPosition) {
                problems +=
                    "${expected.name}.${column.name} primary key position ${actual.primaryKeyPosition}, " +
                    "expected $expectedPkPosition"
            }
            // Room only compares a default when the entity declares one. A column added by an
            // ALTER legitimately carries a DEFAULT that the entity does not (SQLite requires one
            // on `ADD COLUMN ... NOT NULL`), and Room 2.8 tags the live column CREATED_FROM_DATABASE
            // and skips the comparison when the expected default is absent. Enforcing it anyway
            // would fail a database the app opens happily -- the *values* those defaults put into
            // existing rows are what matters, and the upgrade test checks them directly.
            if (column.defaultValue != null && !defaultsMatch(actual.defaultValue, column.defaultValue)) {
                problems +=
                    "${expected.name}.${column.name} default '${actual.defaultValue}', " +
                    "expected '${column.defaultValue}'"
            }
        }

        live.columns.keys.filterNot { it in expectedNames }.forEach {
            problems += "${expected.name}.$it exists in the database but not in the schema"
        }
        return problems
    }

    private fun diffIndices(expected: ExportedTable, live: Table): List<String> {
        val expectedIndices =
            expected.indices.map { Index(it.name, it.unique, it.columns) }.toSet()
        return (expectedIndices - live.indices).map { "${expected.name} is missing index ${it.name}" } +
            (live.indices - expectedIndices).map { "${expected.name} has an unexpected index ${it.name}" }
    }

    private fun diffForeignKeys(expected: ExportedTable, live: Table): List<String> {
        val expectedKeys =
            expected.foreignKeys
                .map {
                    ForeignKey(it.table, it.onDelete, it.onUpdate, it.columns, it.referencedColumns)
                }.toSet()
        return (expectedKeys - live.foreignKeys).map {
            "${expected.name} is missing foreign key ${it.columns} -> ${it.table}${it.referencedColumns}"
        } + (live.foreignKeys - expectedKeys).map {
            "${expected.name} has an unexpected foreign key ${it.columns} -> ${it.table}${it.referencedColumns}"
        }
    }

    companion object {

        /**
         * SQLite affinities as Room derives them from a declared type. Room compares affinities,
         * never the declared type string, so a rename like `INT` to `INTEGER` is not a mismatch
         * while `TEXT` to `INTEGER` is.
         */
        fun affinityOf(declaredType: String): String {
            val type = declaredType.uppercase(Locale.US)
            return when {
                type.contains("INT") -> "INTEGER"
                type.contains("CHAR") || type.contains("CLOB") || type.contains("TEXT") -> "TEXT"
                type.contains("BLOB") || type.isEmpty() -> "BLOB"
                type.contains("REAL") || type.contains("FLOA") || type.contains("DOUB") -> "REAL"
                else -> "NUMERIC"
            }
        }

        /**
         * Room's own default comparison: an absent default matches an absent default, and the
         * spelling differences SQLite and the exporter produce for the same value (`NULL` vs no
         * value, `0` vs `(0)`, `'x'` vs `x`) are not mismatches.
         */
        fun defaultsMatch(live: String?, expected: String?): Boolean {
            if (live == null && expected == null) return true
            if (live == expected) return true
            val left = normalizeDefault(live)
            val right = normalizeDefault(expected)
            return left == right || left.equals(right, ignoreCase = true)
        }

        private fun normalizeDefault(value: String?): String? {
            var text = value?.trim() ?: return null
            while (text.length > 1 && text.startsWith("(") && text.endsWith(")")) {
                text = text.substring(1, text.length - 1).trim()
            }
            text = text.removeSurrounding("'")
            return if (text.equals("NULL", ignoreCase = true)) null else text
        }
    }
}
